"""Hand-written teaching notes.

Each opening has a main line in a PGN-like text where {braces} annotate the move
before them. Notes attach to (position, move), so they also show up in any other
line of the book that reaches the same position, including by transposition.

`mistakes` are tempting wrong moves: (moves before it, the move, why it is wrong).
`sidelines` are extra annotated lines, typically traps worth knowing.
"""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class Curated:
    name: str
    eco: str
    side: str  # the side a student usually trains: "white" or "black"
    summary: str
    white_plan: str
    black_plan: str
    line: str
    mistakes: tuple[tuple[str, str, str], ...] = ()
    sidelines: tuple[str, ...] = ()


def O(name, eco, side, summary, white_plan, black_plan, line, mistakes=(), sidelines=()):
    return Curated(name, eco, side, summary, white_plan, black_plan, line, tuple(mistakes), tuple(sidelines))


# Moves shared by many openings. Annotating them once covers the whole book.
COMMON = (
    "1.e4 {Takes the centre and opens lines for the queen and the f1-bishop at once.}",
    "1.d4 {Takes the centre with a pawn that the queen already protects, which usually leads to slower, more strategic play.}",
    "1.c4 {Controls d5 from the flank. White often keeps the centre flexible and develops around it.}",
    "1.Nf3 {Develops, stops ...e5 for now and keeps White's central pawn choices open.}",
    "1.e4 e5 {Stakes an equal claim in the centre and frees the f8-bishop and the queen.}",
    "1.e4 c5 {Fights for d4 from the flank. The imbalance gives Black real winning chances.}",
    "1.e4 e6 {Prepares ...d5. The c8-bishop gets shut in, which is the French's long-term problem.}",
    "1.e4 c6 {Prepares ...d5 while keeping the c8-bishop's diagonal open: solid, with fewer weaknesses than the French.}",
    "1.d4 d5 {Claims an equal share of the centre and stops e2-e4 for now.}",
    "1.d4 Nf6 {Controls e4 without committing a pawn. Black decides on a structure after seeing White's setup.}",
    "1.e4 e5 2.Nf3 {Develops with tempo by attacking e5.}",
    "1.e4 e5 2.Nf3 Nc6 {Defends e5 while developing, the most natural reply.}",
    "1.d4 Nf6 2.c4 {Grabs more space and takes control of d5.}",
    "1.d4 d5 2.c4 {Attacks d5 to pull a black pawn away from the centre. It is not a true gambit, since the pawn can usually be regained.}",
    "1.d4 Nf6 2.c4 e6 {Opens the f8-bishop and prepares ...d5 or ...Bb4, keeping the choice between several defences.}",
    "1.d4 Nf6 2.c4 g6 {Prepares ...Bg7, aiming the bishop at White's centre rather than occupying it.}",
)

